INSERT INTO `cpdlctypes` (`direction`, `reference_number`, `message_intent`, `message_element`, `response_type`, `fans_1_a`, `fans_1_a_atn_b1`, `atn_b1`) VALUES
('DM', 'DM0', 'The instruction is understood and will be  complied with.', 'WILCO', 'N', 1, 1, 0),
('DM', 'DM1', 'The instruction cannot be complied with.', 'UNABLE', 'N', 1, 1, 0),
('DM', 'DM10', 'Request to descend to the specified level.', 'REQUEST  DESCENT  TO  [level]', 'Y  UM 0  UM 1  UM 19  UM 20  UM 23  UM 26  UM 27  UM 28  UM 29  UM 46  UM 47  UM 48  UM 159 +  UM 183  UM 162  UM 211', 1, 1, 0),
('DM', 'DM100', 'Confirmation  to  the  ground  system  that  the  aircraft  system  has  received  the  message  to  which  the  logical  acknowledgement  refers  and  found  it  acceptable  for  display  to  the  responsible  person.  FANS 1/A  –  ATN B1.—  ATN B1  ground  systems  uses  alternate  means,  such  as  MAS  message  assurance  received  from  FANS 1/A  aircraft,  to  mimic  LOGICAL  ACKNOWLEDGEMENT.', 'LOGICAL  ACKNOWLEDGEMENT', 'N', 0, 0, 0),
('DM', 'DM101', 'Allows  the  pilot  to  indicate  a  desire  for  termination  of  CPDLC  application  with  the current data authority.', 'REQUEST  END  OF  SERVICE', 'Y', 0, 0, 0),
('DM', 'DM102', 'Used to report that an aircraft has landed.', 'LANDING REPORT', 'N', 0, 0, 0),
('DM', 'DM103', 'Allows  the  pilot  to  indicate  that  he/she  has cancelled IFR flight plan.', 'CANCELLING IFR', 'Y', 0, 0, 0),
('DM', 'DM104', 'Notification  of  estimated  time  of  arrival  at the specified position.  FANS 1/A.—  Uses  free  text  DM  67n.   Response to free text UM 169d REPORT  ETA [position]', 'ETA  [position]  [time]  or  [position] [time]', 'N', 1, 0, 0),
('DM', 'DM105', 'Notification of the alternative aerodrome  for landing.', 'ALTERNATE  AERODROME [airport]', 'N', 0, 0, 0),
('DM', 'DM106', 'Notification of the preferred level.  FANS 1/A.—  Uses  DM  67m.    Response  to  free  text  UM  169c  STATE  PREFERRED LEVEL.  FANS 1/A  –  ATN B1.—    FANS 1/A  aircraft  response  to  UM  231  STATE  PREFERRED LEVEL.', 'PREFERRED  LEVEL  [level] or FL[altitude]', 'N', 1, 1, 0),
('DM', 'DM107', 'A  system-generated  message  sent  to  a  ground system that tries to connect to an  aircraft when a current data authority has  not  designated  the  ground  system  as  the  NDA.  FANS 1/A  –  ATN B1.—  ATN B1  aircraft  uses this message.', 'NOT  AUTHORIZED  NEXT  DATA  AUTHORITY', 'N', 0, 0, 0),
('DM', 'DM108', 'Notification that de-icing action has been  completed.', 'DE-ICING COMPLETE', 'N', 0, 0, 0),
('DM', 'DM109', 'Notification  of  the  preferred  time  to  commence descent for approach.  FANS 1/A.— Uses DM 67v.  Response to  free  text  UM  169aa  STATE  TOP  OF  DESCENT.  FANS 1/A  –  ATN B1.—  FANS 1/A  aircraft  response  to  UM  232  STATE  TOP OF DESCENT.', 'TOP  OF  DESCENT  [time] or TOD [time]', 'N', 1, 1, 0),
('DM', 'DM11', 'Request  that  at  the  specified  position  a  climb to the specified level be approved.', 'AT  [position]  REQUEST  CLIMB TO [level]', 'Y', 1, 0, 0),
('DM', 'DM110', 'Notification  of  the  preferred  position  to  commence descent for approach.', 'TOP  OF  DESCENT  [position]', 'N', 0, 0, 0),
('DM', 'DM111', 'Notification  of  the  preferred  time  and  position  to  commence  descent  for  approach.', 'TOP  OF  DESCENT  [time]  [position]', 'N', 0, 0, 0),
('DM', 'DM112', 'Indicates  specifically  that  the  aircraft  is  being subjected to unlawful interference.', 'SQUAWKING 7500', 'N', 0, 0, 0),
('DM', 'DM113', 'Notification of the requested speed.  FANS 1/A.—  Uses  DM  67l  free  text  for  partial  intent.    The  flight  crew  notifies  the  controller  of  present  ground  speed,  in  response  to  UM  169b,  REPORT  GROUND SPEED.', '[speed  type]  [speed  type]  [speed  type]  SPEED  [speed]', 'N', 1, 0, 0),
('DM', 'DM114', 'Notification  that  the  aircraft  is  clear  of  weather and is able to accept a clearance  to regain cleared flight route.', 'CLEAR OF WEATHER', 'N', 0, 0, 0),
('DM', 'DM115', 'We  can  accept  the  specified  level  at  the  specified position.', 'WE  CAN  ACCEPT  [level]  AT [position]', 'N', 0, 0, 0),
('DM', 'DM116', 'We can accept the specified speed at the  specified position.', 'WE CAN ACCEPT [speed]  AT [position]', 'N', 0, 0, 0),
('DM', 'DM117', 'We can accept a parallel track offset the  specified  distance  in  the  specified  direction at the specified position.', 'WE  CAN  ACCEPT  [specified  distance]  [direction] AT [position]', 'N', 0, 0, 0),
('DM', 'DM12', 'Request  that  at  the  specified  position  a  descent  to  the  specified  level  be  approved.', 'AT  [position]  REQUEST  DESCENT TO [level]', 'Y', 1, 0, 0),
('DM', 'DM13', 'Request that at the specified time a climb  to the specified level be approved.', 'AT  [time]  REQUEST  CLIMB TO [level]', 'Y', 1, 0, 0),
('DM', 'DM14', 'Request  that  at  the  specified  time  a  descent  to  the  specified  level  be  approved.', 'AT  [time]  REQUEST  DESCENT TO [level]', 'Y', 1, 0, 0),
('DM', 'DM15', 'Request that a parallel track, offset from  the  cleared  track  by  the  specified  distance  in  the  specified  direction,  be  approved.', 'REQUEST  OFFSET  [specified  distance]  [direction] OF ROUTE', 'Y', 1, 0, 0),
('DM', 'DM16', 'Request that a parallel track, offset from  the  cleared  track  by  the  specified  distance  in  the  specified  direction,  be  approved from the specified position.', 'AT  [position]  REQUEST  OFFSET  [specified  distance]  [direction]  OF  ROUTE', 'Y', 1, 0, 0),
('DM', 'DM17', 'Request that a parallel track, offset from  the  cleared  track  by  the  specified  distance  in  the  specified  direction,  be  approved from the specified time.', 'AT  [time]  REQUEST  OFFSET  [specified  distance]  [direction]  OF  ROUTE', 'Y', 1, 0, 0),
('DM', 'DM18', 'Request to fly at the specified speed.', 'REQUEST [speed]', 'Y  UM 0  UM 1  UM 162  UM 211  UM 55  UM 61  UM 106  UM 107  UM 108  UM 109  UM 116  UM 222  UM 159 +  UM 183', 1, 1, 0),
('DM', 'DM19', 'Request to fly within the specified speed  range.', 'REQUEST  [speed]  TO  [speed]', 'Y', 1, 0, 0),
('DM', 'DM2', 'Wait for a reply.  Note.—  The  controller  is  informed  that  the  request  is  being  assessed  and  there  will  be  a  short-term  delay  (within  10  minutes). The exchange is not closed and  the  request  will  be  responded  to  when  conditions allow.', 'STANDBY', 'N', 1, 1, 0),
('DM', 'DM20', 'Request for voice contact.', 'REQUEST  VOICE  CONTACT', 'Y', 1, 0, 0),
('DM', 'DM21', 'Request  for  voice  contact  on  the  specified frequency.', 'REQUEST  VOICE  CONTACT [frequency]', 'Y', 1, 0, 0),
('DM', 'DM22', 'Request  to  track  from  the  present  position direct to the specified position.', 'REQUEST  DIRECT  TO  [position]', 'Y  UM 0  UM 162  UM 211  UM 74  UM 96  UM 190  UM 159 +  UM 183', 1, 1, 0),
('DM', 'DM23', 'Request  for  the  specified  procedure  clearance.', 'REQUEST  [procedure  name]', 'Y', 1, 0, 0),
('DM', 'DM24', 'Request for a route clearance.', 'REQUEST  CLEARANCE  [route  clearance]  or  REQUEST  [route clearance]', 'Y', 1, 0, 0),
('DM', 'DM25', 'Request for a clearance.  Note.— Either pre-departure or route.', 'REQUEST  [clearance  type]  CLEARANCE  or  REQUEST CLEARANCE', 'Y', 1, 0, 0),
('DM', 'DM26', 'Request  for  a  weather  deviation  to  the  specified position via the specified route.', 'REQUEST  WEATHER  DEVIATION TO [position]  VIA [route clearance]', 'Y', 1, 0, 0),
('DM', 'DM27', 'Request for a weather deviation up to the  specified  distance  off  track  in  the  specified direction.', 'REQUEST  WEATHER  DEVIATION  UP  TO  [specified  distance]  [direction] OF ROUTE', 'Y  UM 0  UM 162  UM 211  UM 64  UM 74  UM 82  UM 96  UM 190  UM 159 +  UM 183', 1, 1, 0),
('DM', 'DM28', 'Notification  of  leaving  the  specified  level.', 'LEAVING [level]', 'N', 1, 0, 0),
('DM', 'DM29', 'Notification  of  climbing  to  the  specified  level.', 'CLIMBING TO [level]', 'N', 1, 0, 0),
('DM', 'DM3', 'Message received and understood.  Note.—  ROGER  is  the  only  correct  response  to  an  uplink  free  text  message.  Under no circumstances will ROGER be  used instead of AFFIRM.', 'ROGER', 'N', 1, 1, 0),
('DM', 'DM30', 'Notification  of  descending  to  the  specified level.', 'DESCENDING TO [level]', 'N', 1, 0, 0),
('DM', 'DM31', 'Notification  of  passing  the  specified  position.', 'PASSING [position]', 'N', 1, 0, 0),
('DM', 'DM32', 'Notification of the present level.', 'PRESENT LEVEL [level]  or  PRESENT  ALTITUDE  [altitude]', 'N', 1, 1, 0),
('DM', 'DM33', 'Notification of the present position.', 'PRESENT  POSITION  [position]', 'N', 1, 0, 0),
('DM', 'DM34', 'Notification of the present speed.', 'PRESENT SPEED [speed]', 'N', 1, 0, 0),
('DM', 'DM35', 'Notification  of  the  present  heading  in  degrees.', 'PRESENT  HEADING  [degrees]', 'N', 1, 0, 0),
('DM', 'DM36', 'Notification  of  the  present  ground  track  in degrees.', 'PRESENT  GROUND  TRACK [degrees]', 'N', 1, 0, 0),
('DM', 'DM37', 'Notification  that  the  aircraft  is  maintaining the specified level.', 'MAINTAINING [level] or  LEVEL [altitude]', 'N', 1, 0, 0),
('DM', 'DM38', 'Read-back of the assigned level.', 'ASSIGNED  LEVEL  [level]  or  ASSIGNED  ALTITUDE [altitude]', 'N', 1, 1, 0),
('DM', 'DM39', 'Read-back of the assigned speed.', 'ASSIGNED  SPEED  [speed]', 'N', 1, 0, 0),
('DM', 'DM4', 'Yes.  Note.—  AFFIRM  is  an  appropriate  response  to  an  uplinked  negotiation  request  message  (e.g.  UM  150  CAN  YOU ACCEPT [level] at [time]).', 'AFFIRM', 'N', 1, 1, 0),
('DM', 'DM40', 'Read-back of the assigned route.', 'ASSIGNED ROUTE [route  clearance]', 'N', 1, 0, 0),
('DM', 'DM41', 'The  aircraft  has  regained  the  cleared  route.', 'BACK ON ROUTE', 'N', 1, 0, 0),
('DM', 'DM42', 'The  next  waypoint  is  the  specified  position.', 'NEXT  WAYPOINT  [position]', 'N', 1, 0, 0),
('DM', 'DM43', 'The  ETA  at  the  next  waypoint  is  as  specified.', 'NEXT  WAYPOINT  ETA  [time]', 'N', 1, 0, 0),
('DM', 'DM44', 'The  next  plus  one  waypoint  is  the  specified position.', 'ENSUING  WAYPOINT  [position]', 'N', 1, 0, 0),
('DM', 'DM45', 'Clarification  of  previously  reported  waypoint passage.', 'REPORTED  WAYPOINT  [position]', 'N', 1, 0, 0),
('DM', 'DM46', 'Clarification  of  time  over  previously  reported waypoint.', 'REPORTED  WAYPOINT  [time]', 'N', 1, 0, 0),
('DM', 'DM47', 'The  specified  (SSR)  code  has  been  selected.', 'SQUAWKING [code]', 'N', 1, 0, 0),
('DM', 'DM48', 'Position report.  Note.—  Reports  the  current  position  of  the aircraft when the flight crew presses  the  button  to  send  this  message.    ATC  expects  position  reports  based  on  this  downlink message.', 'POSITION  REPORT  [position report]', 'N', 1, 0, 0),
('DM', 'DM49', 'Request  for  the  earliest  time  at  which  a  clearance  to  the  specified  speed  can  be  expected.', 'WHEN CAN WE EXPECT  [speed]', 'Y', 1, 0, 0),
('DM', 'DM5', 'No.  Note.—  NEGATIVE  is  an  appropriate  response  to  an  uplinked  negotiation  request  message  (e.g.  UM  150  CAN  YOU ACCEPT [level] at [time]).', 'NEGATIVE', 'N', 1, 1, 0),
('DM', 'DM50', 'Request  for  the  earliest  time  at  which  a  clearance to a speed within the specified  range can be expected.  Note.— This message should not be used  as it is not supported by the appropriate  uplink  message  response:  UM  103,  UM  104 or UM 105.', 'WHEN CAN WE EXPECT  [speed] TO [speed]', 'Y', 1, 0, 0),
('DM', 'DM51', 'Request  for  the  earliest  time  at  which  a  clearance to regain the planned route can  be expected.', 'WHEN CAN WE EXPECT  BACK ON ROUTE', 'Y', 1, 0, 0),
('DM', 'DM52', 'Request  for  the  earliest  time  at  which  a  clearance to descend can be expected.', 'WHEN  CAN  WE  EXPECT  LOWER  LEVEL  or  WHEN  CAN  WE  EXPECT  LOWER  ALTITUDE', 'Y', 1, 0, 0),
('DM', 'DM53', 'Request  for  the  earliest  time  at  which  a  clearance to climb can be expected.', 'WHEN  CAN  WE  EXPECT  HIGHER  LEVEL  or  WHEN  CAN  WE  EXPECT  HIGHER  ALTITUDE', 'Y', 1, 0, 0),
('DM', 'DM54', 'Request  for  the  earliest  time  at  which  a  clearance to cruise climb to the specified  level can be expected.  Note.— This message should not be used  as it is not supported by the appropriate  uplink  message  response:  UM  11,  UM  12, UM 17, or UM 18.', 'WHEN CAN WE EXPECT  CRUISE  CLIMB  TO  [level]', 'Y', 1, 0, 0),
('DM', 'DM55', 'Urgency prefix.  FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', 'PAN PAN PAN', 'Y  or  N', 1, 1, 0),
('DM', 'DM56', 'Distress prefix.  FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', 'MAYDAY  MAYDAY  MAYDAY', 'Y  or  N', 1, 1, 0),
('DM', 'DM57', 'Notification  of  fuel  remaining  and  number of persons on board.   FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', '[remaining  fuel]  OF  FUEL  REMAINING  AND  [persons  on  board]  PERSONS  ON  BOARD  or  [remaining  fuel]  OF  FUEL  REMAINING  AND  [remaining  souls]  SOULS  ON BOARD', 'Y  or  N', 1, 1, 0),
('DM', 'DM58', 'Notification  that  the  pilot  wishes  to  cancel the emergency condition.   FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', 'CANCEL EMERGENCY', 'Y  or  N', 1, 1, 0),
('DM', 'DM59', 'Notification that the aircraft is diverting  to the specified position via the specified  route due to an urgent need.   FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', 'DIVERTING TO [position]  VIA [route clearance]', 'Y  or  N', 1, 1, 0),
('DM', 'DM6', 'Request to fly at the specified level.', 'REQUEST [level]', 'Y  UM 0  UM 1  UM 19  UM 20  UM 23  UM 26  UM 27  UM 28  UM 29  UM 46  UM 47  UM 48  UM 159 +  UM 183  UM 162  UM 211', 1, 1, 0),
('DM', 'DM60', 'Notification that the aircraft is deviating  the  specified  distance  in  the  specified  direction  off  the  cleared  route  and  maintaining  a  parallel  track  due  to  an  urgent need.   FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', 'OFFSETTING  [specified  distance]  [direction]  OF  ROUTE', 'Y  or  N', 1, 1, 0),
('DM', 'DM61', 'Notification  that  the  aircraft  is  descending  to  the  specified  level  due  to  an urgent need.   FANS 1/A  –  ATN B1.—  Ground  system  will  display  message  to  controller  for  FANS 1/A aircraft.', 'DESCENDING TO [level]', 'Y  or  N', 1, 1, 0),
('DM', 'DM62', 'A  system-generated  message  that  the  avionics has detected an error.', 'ERROR [error information]', 'N', 1, 1, 0),
('DM', 'DM63', 'A  system-generated  denial  to  any  CPDLC application message sent from a  ground facility that is not the current data  authority.', 'NOT  CURRENT  DATA  AUTHORITY', 'N', 1, 1, 0),
('DM', 'DM64', 'Notification  to  the  ground  system  that  the  specified  ATSU  is  the  current  data  authority.  FANS 1/A  –  ATN B1.—  FANS 1/A  aircraft uses this message.', '[facility designation]', 'N', 1, 1, 0),
('DM', 'DM65', 'Used  to  explain  reasons  for  pilot’s  message.', 'DUE TO WEATHER', 'N', 1, 1, 0),
('DM', 'DM66', 'Used  to  explain  reasons  for  pilot’s  message.', 'DUE  TO  AIRCRAFT  PERFORMANCE', 'N', 1, 1, 0),
('DM', 'DM67', 'Normal urgency, low alert  FANS 1/A  –  ATN B1.—  FANS 1/A  aircraft only.  ATN B1 aircraft uses DM  98.', '[free text]', 'N', 1, 1, 0),
('DM', 'DM67a', 'Used with a vertical request, indicating an ITP  request  when  there  is  one  reference  aircraft  ahead.  Note 1.— No equivalent in ICAO Doc 4444.', 'ITP  [distance]  BEHIND  [aircraft identification]', 'N', 1, 1, 1),
('DM', 'DM67aa', 'The  specified  ATSU  is  being  monitored  on  the specified frequency.  Urgent urgency attribute.  Note  1.—  Airborne  automation  (i.e.  preformatted  message  rather  than  the  flight  crew  typing  the  text)  may  be  necessary  for  message  composition  and  to  ensure  accuracy  of the message content.  Consequently, not all  aircraft  will  be  equipped  with  such  automation.  Note 2.— Same intent as ICAO Doc 4444 DM  89.', 'MONITORING  [unit  name]  [frequency]', 'N', 1, 1, 1),
('DM', 'DM67ab', 'Notification that the ADS-C emergency mode  was inadvertent and has been set to OFF.  Note.— No equivalent in ICAO Doc 4444.', 'ADS-C RESET', 'N', 1, 1, 1),
('DM', 'DM67ac', 'Used  with  DM  27,  indicating  a  request  for  a  weather deviation on both sides of route.', 'AND  [specified  distance]  [direction]', 'N', 1, 1, 1),
('DM', 'DM67ad', 'Request  for  a  tailored  arrival.    The  TA  designator and speed are optional.  Note 1.— No equivalent in ICAO Doc 4444.  Note  2.—  When  pre-formatting  of  the  downlink  message  is  not  available,  the  flight  crew  can  shorten  to: REQ TA [TA designator]', 'REQUEST  TAILORED  ARRIVAL  [TA  designator]  [speed]  or  REQ  TA  [TA  designator] [speed]', 'N', 1, 1, 1),
('DM', 'DM67ae', 'Notification  from  the  intermediary  CPDLC- capable  aircraft  that  the  aircraft  not  in  communication received the instructions.', 'RELAY  FROM  [call  sign]  [response parameters]', 'N', 1, 1, 1),
('DM', 'DM67af', 'Notification that the aircraft does not have the  functionality of a message latency monitor.  Note 1.— No equivalent in ICAO Doc 4444.  Note  2.—  Response  to  free  text  UM  169au  CONFIRM MAX UPLINK DELAY VALUE IS  NOT  SET  or  UM  169w  SET  MAX  UPLINK  DELAY  VALUE  TO  [delayed  message  parameter] SECONDS.', 'TIMER NOT AVAILABLE', 'N', 1, 1, 1),
('DM', 'DM67ag', 'Used with a vertical request, indicating an ITP  request  when  there  are  two  reference  aircraft,  one ahead and the other behind.  Note 1.— No equivalent in ICAO Doc 4444.', 'ITP  [distance]  BEHIND  [aircraft  identification]  AND  [distance] AHEAD OF [aircraft  identification]', 'N', 1, 1, 1),
('DM', 'DM67b', 'We  can  accept  the  specified  level  at  the  specified time.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 81.', 'WE  CAN  ACCEPT  [altitude]  AT [time]', 'N', 1, 1, 1),
('DM', 'DM67c', 'We  can  accept  the  specified  speed  at  the  specified time.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 83.', 'WE CAN ACCEPT [speed] AT  [time]', 'N', 1, 1, 1),
('DM', 'DM67d', 'We  can  accept  a  parallel  track  offset  the  specified distance in the specified direction at  the specified time.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 85.', 'WE  CAN  ACCEPT  [specified  distance] [direction] AT [time]', 'N', 1, 1, 1),
('DM', 'DM67e', 'We cannot accept the specified level.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 82.', 'WE  CANNOT  ACCEPT  [altitude]', 'N', 1, 1, 1),
('DM', 'DM67f', 'We cannot accept the specified speed.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 84.', 'WE  CANNOT  ACCEPT  [speed]', 'N', 1, 1, 1),
('DM', 'DM67g', 'We  cannot  accept  a  parallel  track  offset  the  specified distance in the specified direction.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 86.', 'WE  CANNOT  ACCEPT  [specified distance] [direction]', 'N', 1, 1, 1),
('DM', 'DM67h', 'Request  for  the  earliest  time  at  which  a  clearance to climb to the specified level can be  expected.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 87.', 'WHEN  CAN  WE  EXPECT  CLIMB TO [altitude]', 'N', 1, 1, 1),
('DM', 'DM67i', 'Request  for  the  earliest  time  at  which  a  clearance to descend to the specified level can  be expected.  Note.—  Intent  equivalent  to  ICAO  Doc  4444  DM 88.', 'WHEN  CAN  WE  EXPECT  DESCENT TO [altitude]', 'N', 1, 1, 1),
('DM', 'DM67j', 'Notification  that  the  transfer  of  the  CPDLC  connection has failed.  Note.— No equivalent in ICAO Doc 4444.', 'CPDLC  TRANSFER  FAILURE', 'N', 1, 1, 1),
('DM', 'DM67k', 'Notification  of  a  revised  estimate  for  the  specified position.  Note.— Intent similar to DM 43.', 'REVISED  ETA  [position]  [time]', 'N', 1, 1, 1),
('DM', 'DM67l', 'Notification of the ground speed.  Note  1.—  Intent  partial  to  ICAO  Doc  4444  DM 113.  Note  2.—  When  pre-formatting  of  the  downlink  message  is  not  available,  the  flight  crew  can  shorten  to: GS [speed]', 'GROUND  SPEED  [speed]  or  GS [speed]', 'N', 1, 1, 1),
('DM', 'DM67m', 'Notification of the preferred level.  Note 1.— Same intent as ICAO Doc 4444 DM  106.  Note  2.—  When  pre-formatting  of  the  downlink  message  is  not  available,  the  flight  crew  can  shorten  to: FL[altitude]', 'PREFERRED  LEVEL  [level]  or FL [altitude]', 'N', 1, 1, 1),
('DM', 'DM67n', 'Notification of estimated time of arrival at the  specified position.  Note 1.— Same intent as ICAO Doc 4444 DM  104.  Note  2.—  When  pre-formatting  of  the  downlink  message  is  not  available,  the  flight  crew  can  shorten  to: [position] [time]', 'ETA  [position]  [time]  or  [position] [time]', 'N', 1, 1, 1),
('DM', 'DM67o', 'Notification  that  the  flight  crew  has  visually  sighted and passed the specified traffic.  Note.— No equivalent in ICAO Doc 4444.', '[traffic  identification]  SIGHTED AND PASSED', 'N', 1, 1, 1),
('DM', 'DM67p', 'Notification  that  the  flight  crew  did  NOT  visually sight the specified traffic.  Note.— No equivalent in ICAO Doc 4444.', '[traffic  identification]  NOT  SIGHTED', 'N', 1, 1, 1),
('DM', 'DM67q', 'Notification  that  the  previously  described  traffic has been sighted.  Note.— No equivalent in ICAO Doc 4444.', 'TRAFFIC SIGHTED', 'N', 1, 1, 1),
('DM', 'DM67r', 'Used with a vertical request, indicating an ITP  request  when  there  is  one  reference  aircraft  behind.  Note 1.— No equivalent in ICAO Doc 4444.', 'ITP  [distance]  AHEAD  OF  [aircraft identification]', 'N', 1, 1, 1),
('DM', 'DM67s', 'Used with a vertical request, indicating an ITP  request  when  there  are  two  reference  aircraft,  both ahead.  Note 1.— No equivalent in ICAO Doc 4444.', 'ITP [distance] BEHIND[aircraft  identification]  AND  [distance]  BEHIND  [aircraft  identification]', 'N', 1, 1, 1),
('DM', 'DM67t', 'Used with a vertical request, indicating an ITP  request  when  there  are  two  reference  aircraft,  both behind.  Note 1.— No equivalent in ICAO Doc 4444.', 'ITP  [distance]  AHEAD  OF  [aircraft  identification]  AND  [distance] AHEAD OF [aircraft  identification]', 'N', 1, 1, 1),
('DM', 'DM67v', 'Notification  of  the  preferred  time  to  commence descent for an approach.  Note 1.— Same intent as ICAO Doc 4444 DM  109.  Note  2.—  When  pre-formatting  of  the  downlink  message  is  not  available,  the  flight  crew  can  shorten  to: TOD [time]', 'TOP  OF  DESCENT  [time]  or  TOD [time]', 'N', 1, 1, 1),
